import React, { useState, useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "../utils/axios";
import AddExpenseForm from "../components/AddExpenseForm";
import ConfirmDeleteModal from "../components/ConfirmDeleteModal";
import { Trash2 } from "lucide-react";

const Expenses = () => {
  const { budgetId } = useParams();
  const navigate = useNavigate();
  const [budget, setBudget] = useState(null);
  const [page, setPage] = useState(1);
  const [showAdd, setShowAdd] = useState(false);
  const [deleteId, setDeleteId] = useState(null);
  const [showBudgetDel, setShowBudgetDel] = useState(false);
  const PER_PAGE = 8;

  const fetchBudget = useCallback(async () => {
    try {
      const email = localStorage.getItem("email");
      const r = await axios.get(`/api/budgets/${budgetId}`, { headers: { email } });
      setBudget(r.data);
    } catch (e) { console.error(e); }
  }, [budgetId]);

  useEffect(() => { fetchBudget(); }, [fetchBudget]);

  if (!budget) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "60vh" }}>
      <div style={{ color: "#9b9b9b", fontSize: 14 }}>Loading…</div>
    </div>
  );

  const expenses = [...(budget.expenses || [])].sort((a, b) => new Date(b.date) - new Date(a.date));
  const spent = expenses.reduce((s, e) => s + (e.amount || 0), 0);
  const pct = budget.amount > 0 ? Math.min((spent / budget.amount) * 100, 100) : 0;
  const over = spent > budget.amount;
  const totalPages = Math.max(1, Math.ceil(expenses.length / PER_PAGE));
  const current = expenses.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const handleDeleteExpense = async () => {
    await axios.delete(`/api/budgets/${budgetId}/expenses/${deleteId}`, { headers: { email: localStorage.getItem("email") } });
    setDeleteId(null);
    fetchBudget();
  };

  const handleDeleteBudget = async () => {
    await axios.delete(`/api/budgets/${budgetId}`, { headers: { email: localStorage.getItem("email") } });
    navigate("/budgets");
  };

  return (
    <div style={{ fontFamily: "'Inter', sans-serif" }}>
      {/* Header */}
      <div style={{ marginBottom: 32 }}>
        <button onClick={() => navigate("/budgets")} style={{ background: "none", border: "none", color: "#9b9b9b", fontSize: 13, cursor: "pointer", padding: 0, marginBottom: 16, display: "flex", alignItems: "center", gap: 4 }}>
          ← Back to Budgets
        </button>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ width: 48, height: 48, borderRadius: 10, background: "#eff6ff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 24 }}>{budget.icon || "💰"}</div>
            <div>
              <h1 style={{ fontSize: 24, fontWeight: 700, color: "#191919", margin: 0, letterSpacing: "-0.02em" }}>{budget.name}</h1>
              <div style={{ fontSize: 13, color: "#9b9b9b", marginTop: 3 }}>RM {spent.toFixed(2)} of RM {(budget.amount || 0).toFixed(2)}</div>
            </div>
          </div>
          <button onClick={() => setShowBudgetDel(true)} style={{ padding: "7px 14px", background: "#fff", border: "1px solid #fecaca", color: "#dc2626", borderRadius: 8, fontSize: 13, cursor: "pointer", fontFamily: "'Inter', sans-serif" }}>
            Delete Budget
          </button>
        </div>
        <div style={{ marginTop: 16, height: 6, background: "#f1f1ef", borderRadius: 3, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${pct}%`, background: over ? "#dc2626" : pct > 80 ? "#d97706" : "#2563eb", borderRadius: 3, transition: "width 0.4s" }} />
        </div>
        <div style={{ fontSize: 12, color: "#9b9b9b", marginTop: 6 }}>{pct.toFixed(0)}% of budget used</div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 340px", gap: 24 }}>
        {/* Expense Table */}
        <div style={{ background: "#fff", border: "1px solid #e8e8e6", borderRadius: 10, overflow: "hidden" }}>
          <div style={{ padding: "16px 20px", borderBottom: "1px solid #e8e8e6", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={{ fontSize: 15, fontWeight: 600, color: "#191919" }}>Expenses</div>
            <span style={{ background: "#f1f1ef", borderRadius: 5, padding: "3px 10px", fontSize: 12, color: "#374151", fontWeight: 500 }}>{expenses.length}</span>
          </div>
          {expenses.length === 0 ? (
            <div style={{ padding: "48px 0", textAlign: "center", color: "#9b9b9b", fontSize: 13 }}>No expenses yet. Add one →</div>
          ) : (
            <>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#fafaf9" }}>
                    {["Description", "Amount", "Date", ""].map(h => (
                      <th key={h} style={{ padding: "10px 20px", fontSize: 11, fontWeight: 600, color: "#9b9b9b", textTransform: "uppercase", letterSpacing: "0.06em", textAlign: h === "Amount" || h === "Date" ? "right" : "left" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {current.map(e => (
                    <tr key={e.id} style={{ borderTop: "1px solid #f1f1ef" }}>
                      <td style={{ padding: "13px 20px", fontSize: 14, color: "#191919" }}>{e.description}</td>
                      <td style={{ padding: "13px 20px", textAlign: "right", fontSize: 14, fontWeight: 600, color: "#191919" }}>RM {(e.amount||0).toFixed(2)}</td>
                      <td style={{ padding: "13px 20px", textAlign: "right", fontSize: 13, color: "#9b9b9b" }}>
                        {e.date ? new Date(e.date).toLocaleDateString("en-MY", { day: "numeric", month: "short" }) : "—"}
                      </td>
                      <td style={{ padding: "13px 20px", textAlign: "right" }}>
                        <button onClick={() => setDeleteId(e.id)} style={{ background: "none", border: "none", color: "#d1d5db", cursor: "pointer", padding: 4, borderRadius: 4 }}
                          onMouseEnter={e2 => e2.currentTarget.style.color = "#dc2626"}
                          onMouseLeave={e2 => e2.currentTarget.style.color = "#d1d5db"}>
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {totalPages > 1 && (
                <div style={{ padding: "12px 20px", borderTop: "1px solid #f1f1ef", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} style={pgBtn}>← Prev</button>
                  <span style={{ fontSize: 13, color: "#9b9b9b" }}>Page {page} of {totalPages}</span>
                  <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} style={pgBtn}>Next →</button>
                </div>
              )}
            </>
          )}
        </div>

        {/* Add Expense */}
        <AddExpenseForm budgetId={budgetId} onExpenseAdded={fetchBudget} />
      </div>

      <ConfirmDeleteModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={handleDeleteExpense} message="Delete this expense?" />
      <ConfirmDeleteModal isOpen={showBudgetDel} onClose={() => setShowBudgetDel(false)} onConfirm={handleDeleteBudget} message="Delete this budget and all its expenses? This cannot be undone." />
    </div>
  );
};

const pgBtn = {
  background: "none", border: "1px solid #e8e8e6", color: "#374151", fontSize: 13,
  padding: "5px 12px", borderRadius: 6, cursor: "pointer", fontFamily: "'Inter', sans-serif",
};

export default Expenses;
